(function(){"use strict";var n=[1,8,14,15,18,23,24,28,29,30],t={斋期:{t:"道教斋期",d:"道教徒持戒、朝真、诵经、礼忏之日。本页斋期由三类合成：其一为十直日，每月固定初一、初八、十四、十五、十八、廿三、廿四、廿八、廿九、三十，为道教最通行之逐日斋期；其二为节令斋，即三会朝真日、三元斋、八节斋、五腊、八会、天赦斋，皆落于特定农历日；其三为庚申甲子守夜，属持行之戒，本页并入斋期一并提示。斋日宜茹素、持戒、诵经、礼忏，不杀生、不荤腥、不兴土木诉讼。"},十直日:{t:"十直日",d:"每月初一、初八、十四、十五、十八、廿三、廿四、廿八、廿九、三十\uFF08小月无三十则退于廿九\uFF09。出自《太上洞玄灵宝福日妙经》等，为道教最通行之逐日斋期，谓此十日诸天诸真下降察人功过，宜斋戒修善。每月十日，全年约一百二十日，与佛历六斋、十斋、朔望斋部分日期重合而分属两教体系。"},三会朝真:{t:"三会朝真日",d:"正月七日举迁赏会、七月七日庆生中会、十月十五日建生大会，为道教三官大帝集会考校人之功过之期，宜朝真礼忏。本页以三会日承接朝真斋，与三元斋同列斋期，二者分属不同经典出处：三会主集会考校，三元主赐福赦罪解厄。"},三元斋:{t:"三元斋",d:"上元正月十五天官赐福、中元七月十五地官赦罪、下元十月十五水官解厄，为三官大帝圣诞与考校之期，道教重大斋日。上元赐福、中元赦罪、下元解厄，谓此三日三官同天地二官考校罪福。"},八节斋:{t:"八节斋",d:"立春、春分、立夏、夏至、立秋、秋分、立冬、冬至八节气，各有一方天尊同对应帝君九炁天君下降，为道教朝真斋期。"},五腊:{t:"五腊日",d:"正月一日天腊、五月五日地腊、七月七日道德腊、十月一日民岁腊、十二月八日王侯腊，为五帝校定生人罪福之辰。五腊皆酌水献花以祀先祖五帝，道教重要斋祭之日。"},八会:{t:"八会日",d:"丙午天会、壬午地会、壬子人会、庚午日会、庚申月会、辛酉星辰会、甲辰五行会、甲戌四时会，为道教诸真集会之期，宜修斋奉道。八会日不属逐日斋戒，本页列于斋期一并提示。"},天赦斋:{t:"天赦斋",d:"春戊寅、夏甲午、秋戊申、冬甲子为天赦日，古谓天地赦过宥罪之辰，宜修身、祈福、恕罪、施恩。"},庚申甲子守夜:{t:"庚申甲子守夜",d:"庚申日与甲子日为道教守静之期：庚申日传为人身三尸神上天言人罪过之日，甲子日为六十甲子之首、诸神校计之辰，两日宜清静守一、不熬夜喧扰、检束身心。守夜属持行之戒而非茹素之斋，本页并入斋期一并提示。"},圣诞:{t:"神仙圣诞",d:"道教神仙诞生之辰，本页以节日名含“诞”者标识于日历右上角“诞”字。名号含“圣诞”或“诞”者皆属此类，如老君圣诞、玉皇圣诞、邱祖圣诞等。名含“下降”者归下降，名含“成道”“飞升”“得道”者归成道，余者归节日。"},下降:{t:"神仙下降",d:"道教谓神仙于此日自天界下降人间，巡化度人之期，如八节天尊下降、南斗星君下降等。下降日与圣诞、成道日并列，属道教节日而不称诞。玉帝巡天不含下降二字，归节日类。"},成道:{t:"神仙成道",d:"道教神仙证道、飞升、成道之辰，如邱祖飞升、孙真君成道、许真君飞升等。成道日与圣诞并列，属道教节日而不称诞。"},节日:{t:"道教节日",d:"不属圣诞、下降、成道三类的道教节庆通名，如三会日的会名\uFF08天会、地会、人会\uFF09、天腊五腊、巡天祭灶、北斗九皇降世等。盘与详情条按类目冠名，全名列于详情条。"},吉日:{t:"道教吉日",d:"三会日、三元日、八节日、八会日、五腊日、天赦日六类，为道教宜行朝真礼忏修斋之事的日子。六类各依其节令或日辰定日，名目逐日列于圣诞斋日盘下详情条，各类释义见本弹窗其余各条。"},祭灶:{t:"祭灶",d:"腊月廿三北方祭灶，腊月廿四南方祭灶，两说并列；最宜谢旧年太岁、开启拜新年太岁，为道教与民俗共行之仪。"},戊日:{t:"戊日\uFF08明戊、暗戊\uFF09",d:"逢戊不朝真。明戊为日干逢戊\uFF08戊子、戊寅、戊辰、戊午、戊申、戊戌\uFF09，暗戊按农历月支循环定日\uFF08如正月未日、二月戌日等\uFF09。戊日为道教禁忌日，道观停止焚香、诵经、上表，谓戊日诸神朝真，人间不宜动法事。"},三元节:{t:"三元节",d:"上元正月十五、中元七月十五、下元十月十五，为三官大帝圣诞与考校之节，详见三元斋。"},三会日:{t:"三会日",d:"正月七日、七月七日、十月十五日，三官大帝集会考校之期，详见三会朝真。"},八节:{t:"八节",d:"立春、春分、立夏、夏至、立秋、秋分、立冬、冬至，八卦之节，八节天尊下降，详见八节斋。"},黄帝纪元:{t:"黄帝纪元\uFF08道历纪年\uFF09",d:"道历以黄帝纪元为始，纪年即轩辕黄帝纪元之年数，随农历置闰、年界随农历正月初一。黄帝纪元年号有加二六九七与加二六九八两种通行算法，差在黄帝即位之年是否计入，本站采加二六九七。道历与佛历分属两套纪年体系，道历以黄帝纪元起算，佛历以佛灭起算，两者相差约二千一百五十四年，不可直接加减换算。"},京房八宫:{t:"京房八宫\uFF08世应\uFF09",d:"京房易把六十四卦分隶八宫，每宫以一纯卦为首，依一世至五世、游魂、归魂次第变爻成八卦。世爻标一卦之主位：本宫世上爻、一世至五世世在所变之爻、游魂世在第四爻、归魂世在第三爻；应爻与世爻相隔三位，为内外卦相应之位。世应重建即由卦名拆上、下卦合成六爻，查八宫次第定宫与世应。"},十二消息卦:{t:"十二消息卦\uFF08辟卦\uFF09",d:"又称十二辟卦，以十二卦配十二月，表阴阳消长：复一阳生\uFF08子月\uFF09、临二阳\uFF08丑月\uFF09、泰三阳\uFF08寅月\uFF09、大壮四阳\uFF08卯月\uFF09、夬五阳\uFF08辰月\uFF09、乾六阳\uFF08巳月\uFF09为息卦，阳息自子至巳；姤一阴生\uFF08午月\uFF09、遁二阴\uFF08未月\uFF09、否三阴\uFF08申月\uFF09、观四阴\uFF08酉月\uFF09、剥五阴\uFF08戌月\uFF09、坤六阴\uFF08亥月\uFF09为消卦，阴消自午至亥。本页以节气月\uFF08交节换月\uFF09配卦，为卦气说之骨干，出孟喜一系。"},六日七分:{t:"六日七分",d:"孟喜卦气说之值日法：坎、离、震、兑四正卦主四时二十四气\uFF08二至二分各居其首\uFF09，不入值日；其余六十卦每卦直六日七分\uFF08一岁三百六十五又四分之一日、均分六十卦\uFF09，自冬至初中孚用事，次第直日、终而复始。《新唐书·历志》一行卦议引孟喜章句：当据孟氏，自冬至初中孚用事。六十卦逐日值序须依孟喜卦气图全序，本页未逐日排卦，仅录其法。"},正一全真差异:{t:"正一与全真节日体系差异",d:"道教分正一、全真两大流派，节日体系有异：正一派以张天师世系为中心，重天师圣诞、雷祖、酆都大帝等；全真派以王重阳及北七真为中心，重邱处机、王处一、刘处玄、谭处端、孙不二等真人圣诞与飞升。本页节日表兼收两派神祇圣诞与下降、成道之辰，未作流派分列。同一神祇在宫观实际奉祀与庆贺之期，各宫观或有出入。"}};function i(d){return d&&t[d]||null}window.DAO_DICT=t,window.DAO_SHI_ZHI=n,window.daoMean=i})();
